import math

def dist(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def single_linkage(gA, gB):
    return min(dist(a, b) for a in gA for b in gB)

points = [[1], [2], [8], [9], [10]]
clusters = [[p] for p in points]

while len(clusters) > 2:
    best, bi, bj = float('inf'), 0, 1
    for i in range(len(clusters)):
        for j in range(i + 1, len(clusters)):
            d = single_linkage(clusters[i], clusters[j])
            if d < best:
                best, bi, bj = d, i, j
    merged = clusters[bi] + clusters[bj]
    clusters = [c for k, c in enumerate(clusters) if k not in (bi, bj)] + [merged]
    print(f"Merged at dist={best:.1f}: {sorted([p[0] for p in merged])}")
